.catalog-container {
    display: flex;
    gap: 1.5rem;
}

.catalog-sidebar {
    width: 25%;
    min-width: 220px;
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    align-self: flex-start;
}

.catalog-main {
    width: 75%;
    flex: 1;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h5 {
    margin-bottom: 0.5rem;
    font-size: 0.95rem;
    font-weight: 600;
}

.filter-actions {
    margin-top: 1.5rem;
}

.catalog-toolbar {
    padding: 0.75rem 0;
    border-bottom: 1px solid #dee2e6;
    margin-bottom: 1rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 1.25rem;
    margin-bottom: 2rem;
}

.pagination-controls {
    margin-top: 1.5rem;
}

